package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct {
	TcSensor string
	TcF      decimal.Decimal
}

var WsEofFlag string = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0)
var WsFreeze int64 = 0
var WsCount int64 = 0
var WsFEd string
var WsCEd string

var tempRec TempRec

var tempFile *bufio.Scanner
var tempFileHandle *os.File

func formatZZ9_9(v decimal.Decimal) string {
	// PIC ZZ9.9 width 5
	// integer digits = 3, scale 1
	neg := v.Sign() < 0
	if neg {
		v = v.Neg()
	}
	// truncate/pad to scale 1? MOVE does not round? For display, value already fits scale.
	// Ensure scale 1 truncated
	v = v.Truncate(1)
	// Format with integer part 3 digits, one decimal
	// v = intPart + frac
	intPart := v.Truncate(0)
	fracPart := v.Sub(intPart).Abs()

	// get integer digits as 3-char string zero padded low-order
	intInt := intPart.IntPart()
	if intInt < 0 {
		intInt = -intInt
	}
	intInt = intInt % 1000
	intStr := fmt.Sprintf("%03d", intInt)

	fracInt := fracPart.Mul(decimal.NewFromInt(10)).Truncate(0).IntPart()
	// build integer zone with Z suppression
	chars := []byte(intStr)
	// Z positions are first 2
	suppress := true
	for i := 0; i < 2; i++ {
		if chars[i] == '0' && suppress {
			chars[i] = ' '
		} else {
			suppress = false
		}
	}
	// chars[2] is '9' always digit (already)
	result := string(chars) + "." + fmt.Sprintf("%01d", fracInt)
	if neg {
		// For unsigned edited field, sign not shown? But TC-F is always positive per PIC 9(3)V9, so ignore.
	}
	return result
}

func formatMinusZZ9_99(v decimal.Decimal) string {
	// PIC -ZZ9.99 width 7 : sign char + ZZ9 + '.' + 99
	neg := v.Sign() < 0
	av := v
	if neg {
		av = av.Neg()
	}
	av = av.Truncate(2)
	intPart := av.Truncate(0)
	fracPart := av.Sub(intPart).Abs()
	intInt := intPart.IntPart()
	if intInt < 0 {
		intInt = -intInt
	}
	intInt = intInt % 1000
	intStr := fmt.Sprintf("%03d", intInt)
	fracInt := fracPart.Mul(decimal.NewFromInt(100)).Truncate(0).IntPart()
	fracStr := fmt.Sprintf("%02d", fracInt)

	chars := []byte(intStr)
	suppress := true
	for i := 0; i < 2; i++ {
		if chars[i] == '0' && suppress {
			chars[i] = ' '
		} else {
			suppress = false
		}
	}
	signChar := ' '
	if neg {
		signChar = '-'
	}
	result := string(signChar) + string(chars) + "." + fracStr
	return result
}

func formatPIC99(v int64) string {
	// PIC 99 zero padded 2 digits, low-order kept
	if v < 0 {
		v = -v
	}
	v = v % 100
	return fmt.Sprintf("%02d", v)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseTempRec(line string) {
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	}
	if len(line) > 8 {
		line = line[:8]
	}
	tempRec.TcSensor = line[0:4]
	field := line[4:8]
	field = strings.TrimSpace(field)
	if field == "" {
		field = "0"
	}
	// field contains digits only
	// PIC 9(3)V9 => 4 digits, scale 1
	var n int64
	fmt.Sscanf(field, "%d", &n)
	// field may have spaces? Already trimmed; but if shorter due to spaces, Sscanf still works
	// However if original line had spaces padding, we padded; but digits with leading zeros preserved.
	// Better parse exactly digits: keep only 0-9
	digits := ""
	for _, ch := range line[4:8] {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		} else {
			// treat as 0? COBOL would be space but record shorter? ignore
		}
	}
	if digits == "" {
		digits = "0"
	}
	var iv int64
	fmt.Sscanf(digits, "%d", &iv)
	tempRec.TcF = decimal.New(iv, -1)
}

func mainPara() {
	// OPEN INPUT TEMP-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as empty
		WsEofFlag = "N"
	} else {
		tempFileHandle = f
		tempFile = bufio.NewScanner(f)
	}
	readPara()
	for !isInputDone() {
		processPara()
	}
	if tempFileHandle != nil {
		tempFileHandle.Close()
	}
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	wsCountStr := formatPIC99(WsCount)
	wsFreezeStr := formatPIC99(WsFreeze)
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", wsCountStr, wsFreezeStr)
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func readPara() {
	if tempFile == nil {
		WsEofFlag = "Y"
		return
	}
	if tempFile.Scan() {
		line := tempFile.Text()
		// Remove trailing \r if any (LINE SEQUENTIAL)
		line = strings.TrimRight(line, "\r")
		parseTempRec(line)
	} else {
		WsEofFlag = "Y"
	}
}

func processPara() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	diff := tempRec.TcF.Sub(decimal.NewFromInt(32))
	mul := diff.Mul(decimal.NewFromInt(5))
	// divide by 9
	div := mul.Div(decimal.NewFromInt(9))
	// ROUNDED to scale 2
	rounded := div.Round(2)
	// MOVE to WS-C PIC S9(3)V99 : keep low-order digits, truncate to 2 decimals (already)
	// Simulate storage truncation and overflow
	// Truncate to 2 decimals (rounded already is 2)
	stored := rounded.Truncate(2)
	// overflow: keep low-order integer digits (3)
	// For decimal, we need to drop high-order digits
	// Implement by extracting integer part modulo 1000, preserve sign and fractional part
	signNeg := stored.Sign() < 0
	absStored := stored.Abs()
	intPart := absStored.Truncate(0)
	frac := absStored.Sub(intPart)
	intVal := intPart.IntPart() % 1000
	newAbs := decimal.NewFromInt(intVal).Add(frac)
	if signNeg {
		newAbs = newAbs.Neg()
	}
	WsC = newAbs

	if WsC.Cmp(decimal.NewFromInt(0)) < 0 {
		WsFreeze += 1
		WsFreeze = WsFreeze % 100 // PIC 99 overflow low-order
	}
	WsCount += 1
	WsCount = WsCount % 100

	WsFEd = formatZZ9_9(tempRec.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	// TC-SENSOR is X(4) exactly 4 chars
	sensor := padRight(tempRec.TcSensor, 4)
	fmt.Printf("%s %sF %sC\n", sensor, WsFEd, WsCEd)
	// PERFORM READ-PARA
	readPara()
}

func main() {
	mainPara()
}
